import{_ as t,o as d,c as o,ax as a}from"./chunks/framework.Bnt0oLax.js";const m=JSON.parse('{"title":"Command Reference","description":"Every Developer Studio CLI command, its flags, and its exit behavior.","frontmatter":{"description":"Every Developer Studio CLI command, its flags, and its exit behavior."},"headers":[],"relativePath":"cli/reference/commands.md","filePath":"cli/reference/commands.md"}'),r={name:"cli/reference/commands.md"};function s(n,e,i,c,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/cli/reference/commands.md for this page in Markdown format</div><h1 id="command-reference" tabindex="-1">Command Reference <a class="header-anchor" href="#command-reference" aria-label="Permalink to &quot;Command Reference&quot;">​</a></h1><p>Documents every <code>gsds</code> subcommand at version <code>1.2.0</code>. Every command exits <code>0</code> on success and <code>1</code> on any failure. Only <code>gsds preview</code> and <code>gsds connector test</code> require an active session.</p><h2 id="gsds-init" tabindex="-1"><code>gsds init</code> <a class="header-anchor" href="#gsds-init" aria-label="Permalink to &quot;`gsds init`&quot;">​</a></h2><p>Scaffolds a new project. Writes <code>gsds.json</code>, empty <code>extensions_registry.json</code> and <code>connectors_registry.json</code>, <code>AGENTS.md</code>, <code>README.md</code>, and a <code>.gitignore</code> that excludes <code>.gsds/</code>.</p><table tabindex="0"><thead><tr><th>Argument</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;name&gt;</code></td><td>Yes</td><td>Directory to create</td></tr><tr><td><code>--force</code></td><td>No</td><td>Allow initializing into a non-empty directory</td></tr></tbody></table><h2 id="gsds-login" tabindex="-1"><code>gsds login</code> <a class="header-anchor" href="#gsds-login" aria-label="Permalink to &quot;`gsds login`&quot;">​</a></h2><p>Redeems a pairing code, reports the current session, or does nothing when no arguments are provided.</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;pairing_code&gt;</code></td><td>Redeem a pairing code from <strong>Integrations → Developer Studio → CLI Access</strong> in the community. Codes expire 1 minute after issue</td></tr><tr><td><code>--status</code></td><td>Print the current session&#39;s tenant binding and validity</td></tr></tbody></table><p>The resulting session lasts approximately 8 hours and is tenant-scoped. There is no refresh flow.</p><h2 id="gsds-logout" tabindex="-1"><code>gsds logout</code> <a class="header-anchor" href="#gsds-logout" aria-label="Permalink to &quot;`gsds logout`&quot;">​</a></h2><p>Clears the stored session. No flags.</p><h2 id="gsds-create" tabindex="-1"><code>gsds create</code> <a class="header-anchor" href="#gsds-create" aria-label="Permalink to &quot;`gsds create`&quot;">​</a></h2><p>Scaffolds a widget under <code>widgets/&lt;name&gt;/</code>. Interactive in a TTY; in a non-TTY the three flags below are required and the command fails fast when any is missing.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Required (non-TTY)</th><th>Description</th></tr></thead><tbody><tr><td><code>--name</code></td><td>Yes</td><td>Widget slug</td></tr><tr><td><code>--framework</code></td><td>Yes</td><td>One of <code>react</code>, <code>vue</code>, <code>angular</code>, <code>vanilla</code>, <code>html</code></td></tr><tr><td><code>--category</code></td><td>Yes</td><td>Category label used in the No-Code Builder</td></tr></tbody></table><h2 id="gsds-list" tabindex="-1"><code>gsds list</code> <a class="header-anchor" href="#gsds-list" aria-label="Permalink to &quot;`gsds list`&quot;">​</a></h2><p>Lists Extensions in the current project.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--json</code></td><td>Emit a keyed object <code>{ widgets, connectors, scripts, stylesheets }</code> instead of a table. Not a bare array</td></tr></tbody></table><h2 id="gsds-preview" tabindex="-1"><code>gsds preview</code> <a class="header-anchor" href="#gsds-preview" aria-label="Permalink to &quot;`gsds preview`&quot;">​</a></h2><p>Boots a local dev server, registers a preview session with the paired community, and makes local widgets appear in the No-Code Builder picker.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--port</code></td><td>Override the default preview port</td></tr><tr><td><code>--widget &lt;name&gt;</code></td><td>Restrict the preview to specific widgets. Repeatable</td></tr></tbody></table><p>Requires an active session. Each widget must declare a <code>dev</code> script in its <code>package.json</code> to appear in the picker. The package manager for each widget is auto-detected from that widget&#39;s lockfile.</p><h2 id="gsds-build" tabindex="-1"><code>gsds build</code> <a class="header-anchor" href="#gsds-build" aria-label="Permalink to &quot;`gsds build`&quot;">​</a></h2><p>Regenerates <code>extensions_registry.json</code> and <code>connectors_registry.json</code> from source.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--validate</code></td><td>Compare registries against source and exit <code>1</code> on drift. Does not rebuild <code>dist/</code>. Intended as a CI gate</td></tr></tbody></table><p>Every <code>widget.json</code> must declare a non-empty <code>title</code> and <code>category</code>, or the build fails and names the offending file.</p><h2 id="gsds-connector-test" tabindex="-1"><code>gsds connector test</code> <a class="header-anchor" href="#gsds-connector-test" aria-label="Permalink to &quot;`gsds connector test`&quot;">​</a></h2><p>Runs a Connector against the paired tenant. Every run reports whether it was resolved locally (<code>source: local</code>) or from the tenant (<code>source: remote</code>).</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>[name]</code></td><td>Connector to run. Resolution is local-first: matches under <code>widgets/*/connectors.json</code> before matches on the tenant</td></tr><tr><td><code>--payload @&lt;file&gt;</code></td><td>Path to a JSON file containing the request body. File reference only — inline JSON is rejected</td></tr><tr><td><code>--query k=v</code></td><td>Query parameter. Repeatable</td></tr><tr><td><code>--path-param k=v</code></td><td>Path parameter. Repeatable</td></tr><tr><td><code>--verbose</code></td><td>Print the rendered upstream request</td></tr><tr><td><code>--json</code></td><td>Emit a machine-readable result</td></tr></tbody></table><p>Requires an active session. Composite Connectors cannot be tested.</p><p>Every run is captured under <code>.gsds/</code> with sensitive headers redacted.</p><h2 id="gsds-script-and-gsds-style" tabindex="-1"><code>gsds script</code> and <code>gsds style</code> <a class="header-anchor" href="#gsds-script-and-gsds-style" aria-label="Permalink to &quot;`gsds script` and `gsds style`&quot;">​</a></h2><p>Manage sitewide scripts and stylesheets. Both commands share the same subcommand shape.</p><h3 id="subcommands" tabindex="-1">Subcommands <a class="header-anchor" href="#subcommands" aria-label="Permalink to &quot;Subcommands&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Subcommand</th><th>Description</th></tr></thead><tbody><tr><td><code>new &lt;slug&gt;</code></td><td>Scaffold a local file and register it</td></tr><tr><td><code>link &lt;url&gt;</code></td><td>Register an external hosted URL. Must end in <code>.js</code> for scripts, <code>.css</code> for stylesheets</td></tr><tr><td><code>ls</code></td><td>List registered entries</td></tr><tr><td><code>rm &lt;slug&gt;</code></td><td>Remove an entry</td></tr></tbody></table><h3 id="flags-on-new-and-link" tabindex="-1">Flags on <code>new</code> and <code>link</code> <a class="header-anchor" href="#flags-on-new-and-link" aria-label="Permalink to &quot;Flags on `new` and `link`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Applies to</th><th>Description</th></tr></thead><tbody><tr><td><code>--attr k=v</code></td><td>Both</td><td>HTML attribute on the injected tag. Repeatable</td></tr><tr><td><code>--page &lt;name&gt;</code></td><td>Both</td><td>Scope injection to a single page instead of sitewide</td></tr><tr><td><code>--placement head|bodyStart|bodyEnd</code></td><td>Scripts only</td><td>Where to inject the script tag</td></tr><tr><td><code>--name &lt;slug&gt;</code></td><td><code>link</code> only</td><td>Explicit slug. When omitted, the slug is derived from the URL</td></tr></tbody></table><h3 id="flags-on-rm" tabindex="-1">Flags on <code>rm</code> <a class="header-anchor" href="#flags-on-rm" aria-label="Permalink to &quot;Flags on `rm`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--force</code></td><td>Delete a folder that is not empty</td></tr></tbody></table><h2 id="global-flags" tabindex="-1">Global flags <a class="header-anchor" href="#global-flags" aria-label="Permalink to &quot;Global flags&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>--version</code></td><td>Print the installed CLI version and exit</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>Session model → <a href="./../authenticate.html">Authenticate</a></li><li>On-disk files → <a href="./project-files.html">Project files</a></li><li>Error messages → <a href="./troubleshooting.html">Troubleshooting</a></li></ul>',43)])])}const p=t(r,[["render",s]]);export{m as __pageData,p as default};
